# Lesson 10 of MKTG90037: independent sales forces (Week 6, second half). Brands: Lipton and Coles, as a reading (nothing about
# which retailers stock Lipton in Australia was verified); Tesla, Apple, Toyota, Sephora and Foot Locker are the lecture's cases.
# Instruments: expectancy dial (Dial), make or buy a sales force (Place), outcome or behaviour control (Place).
from mk import *  # noqa: F403


def L10(CID):
    SK = 'mk.salesforce'
    mb_zones = [dict(id='make', label=T('Make: build your own sales force', '自建：建自己的销售队伍')), dict(id='buy', label=T('Buy: use independent sellers', '外购：用独立的销售方'))]
    mb_chips = [
        dict(id='m1', label=T('Complex products that need deep product knowledge', '需要深入产品知识的复杂产品'), zone='make', why=T('Specialised knowledge is hard to hand to outsiders.', '专门知识很难交给外人。')),
        dict(id='m2', label=T('Customer relationships are strategic', '客户关系具有战略意义'), zone='make', why=T('You want the relationship to be yours.', '你要让这份关系归你。')),
        dict(id='m3', label=T('Sellers’ effort is hard to monitor', '销售人员的努力难以监督'), zone='make', why=T('Hard-to-watch effort is safer inside, where you can direct it.', '难监督的努力放在内部更稳妥，你能指挥它。')),
        dict(id='b1', label=T('Simple, standardised products', '简单、标准化的产品'), zone='buy', why=T('Little knowledge needed, so outsiders sell them as well.', '不需要多少知识，外部销售一样卖得好。')),
        dict(id='b2', label=T('Sales results are easy to measure', '销售结果容易衡量'), zone='buy', why=T('Easy-to-measure activities can be paid by results.', '容易衡量的活动可以按结果付酬。')),
        dict(id='b3', label=T('Buyers are spread over wide areas', '买家分布在很广的区域'), zone='buy', why=T('Outsiders already cover the ground.', '外部销售方已经覆盖了这些地方。')),
        dict(id='b4', label=T('Cost efficiency is the main concern', '成本效率是主要关切'), zone='buy', why=T('Specialist outsiders can do standard sales more cheaply.', '专业的外部方做标准化销售更便宜。')),
    ]
    ct_zones = [dict(id='beh', label=T('Behaviour-based control', '行为控制')), dict(id='out', label=T('Outcome-based control', '结果控制'))]
    ct_chips = [
        dict(id='c1', label=T('Monitored closely and given direction', '被密切监督并受到指导'), zone='beh', why=T('More frequent monitoring and direction.', '更频繁的监督和指导。')),
        dict(id='c2', label=T('Judged on input, with subjective and complex measures', '按投入来评价，用主观而复杂的指标'), zone='beh', why=T('Evaluation of how they work.', '评价的是他们怎样工作。')),
        dict(id='c3', label=T('A larger share of pay is fixed salary', '薪酬里固定工资占比更大'), zone='beh', why=T('Pay is not tied to each result.', '薪酬不与每笔结果挂钩。')),
        dict(id='c4', label=T('Monitored rarely and given little direction', '很少被监督，也很少受指导'), zone='out', why=T('Less frequent monitoring, little direction.', '监督少、指导少。')),
        dict(id='c5', label=T('Judged on objective, simple outcome measures such as sales', '按销量等客观、简单的结果指标来评价'), zone='out', why=T('Evaluation of what they achieve.', '评价的是他们取得了什么。')),
        dict(id='c6', label=T('A larger share of pay is variable incentive', '薪酬里可变激励占比更大'), zone='out', why=T('Pay moves with the result.', '薪酬随结果变化。')),
    ]
    return dict(
        id=f'{CID}-salesforce',
        title=T('How do I make people who sell for several brands sell mine?', '怎样让同时卖好几个品牌的人，多卖我的？'),
        description=T('Why an independent seller’s motivation is a product of three numbers, when to build or rent a sales force, and how to control and bind it.', '为什么独立销售方的动力是三个数的乘积、何时自建或外购销售队伍，以及怎样控制和绑定它。'),
        minutes=40,
        skills=[{'id': SK, 'name': T('Explaining and applying independent sales force management', '解释并应用独立销售队伍管理')}],
        misconceptions=[
            {'id': 'incentive-is-cash', 'description': T('more cash is always the strongest way to motivate a sales force', '更多的现金总是最强的销售队伍激励方式')},
            {'id': 'motivation-is-sum', 'description': T('motivation is the sum of the three expectancy factors, so one strong factor is enough', '动力是三个期望因素之和，所以一个因素强就够了')},
        ],
        steps=[
            read('puzzle', T('The seller who has other brands on the shelf', '货架上还有别家品牌的销售方'),
                 p(T("Suppose a tea brand reaches shoppers mainly through supermarkets that stock many brands and have their own ranges (this is a reading of how a brand such as Lipton reaches its shoppers; nothing about which stores stock it in Australia is verified). The staff and shelves belong to the retailer, not the brand. In another case, Elon Musk did not want to sell Tesla cars through traditional dealers, because dealers would protect their existing sales rather than promote electric cars as hard as Tesla would.",
                     "假设一个茶叶品牌主要通过同时摆很多品牌、还有自有品牌的超市触达购物者（这是对 Lipton 这类品牌如何触达购物者的解读；哪些门店在澳大利亚上架它并未核实）。员工和货架属于零售商，不属于品牌。再看另一个例子：Elon Musk 不想通过传统经销商卖 Tesla，因为经销商会优先保护自己已有的销售，而不会像 Tesla 自己那样卖力推广电动车。")),
                 p(T("An independent seller is free to push any brand. **Why would it push yours?**", "独立的销售方可以自由地推任何一个品牌。**它为什么要推你的？**")), chapter=CH['puzzle']),
            predict('guess', SK, T("A dealer rates three things at 90% each: it can reach the target, hitting it brings a reward, and it likes the reward. Then it believes the reward is worthless (valence near 0). How motivated is it?", "一家经销商对三件事各打 90 分：它能达到目标、达到后有回报、它喜欢那份回报。后来它认为回报一文不值（效价接近 0）。它的动力是多少？"),
                    [(T("Almost none: the three factors multiply, so one near zero cancels the others", "几乎没有：三个因素相乘，一个接近零，就把其他的都抵消了"), True),
                     (T("Still about 60%: the other two are strong", "还有大约 60%：另外两个很强"), T("If motivation were a sum, yes. Vroom’s theory multiplies.", "如果动力是加总，才是这样。Vroom 的理论是相乘。")),
                     (T("It depends only on the cash", "只取决于现金"), T("Cash is one form of reward; whether it counts depends on whether this seller values it.", "现金只是回报的一种；算不算数取决于这个销售方是否看重它。")),
                     (T("It will sell more because the target is reachable", "它会卖得更多，因为目标够得着"), T("Expectancy alone does not move people.", "只有期望本身不会让人行动。"))],
                    T("The three factors multiply, so a seller with one factor near zero has almost no motivation. Try it with the dial.", "三个因素是相乘的，所以只要一个因素接近零，销售方就几乎没有动力。用转盘试试。")),
            read('touch', T('Multiply the three', '三个数相乘'),
                 p(T("Vroom’s expectancy theory: motivation = **expectancy** (can I hit the target?) × **instrumentality** (will hitting it bring a reward?) × **valence** (do I want the reward?). The dial compares one dealer’s push for your brand with its push for a rival brand it already sells. The numbers are illustrations.", "Vroom 的期望理论：动力 = **期望**（我能达到目标吗？）× **工具性**（达到后有回报吗？）× **效价**（我想要这个回报吗？）。转盘比较同一个销售方推你的品牌和推它已经在卖的竞争品牌，两者的动力。数字只是示意。")),
                 dial(T('Three sliders for expectancy, instrumentality and valence of a seller for your brand; the bars compare its motivation for your brand with its motivation for a rival brand.', '三个滑块代表销售方对你的品牌的期望、工具性和效价；柱状条比较它推你的品牌与推竞争品牌的动力。'),
                      sliders=[dict(id='e', label=T('Expectancy: can we reach the target?', '期望：我们能达到目标吗？'), min=0, max=100, step=5, value=70, unit='%'),
                               dict(id='i', label=T('Instrumentality: does reaching it bring a reward?', '工具性：达到后会有回报吗？'), min=0, max=100, step=5, value=70, unit='%'),
                               dict(id='v', label=T('Valence: how much do we want the reward? (0 to 10)', '效价：我们多想要这份回报？（0 到 10）'), min=0, max=10, step=1, value=7)],
                      consts=dict(rival=24),
                      outs=[dict(id='mine', label=T('Push for your brand', '推你的品牌的动力'), expr='e/100*i/100*v*10', dec=0, bar=dict(max=100)), dict(id='rv', label=T('Push for the rival brand it already sells', '推已在卖的竞争品牌的动力'), expr='rival', dec=0, bar=dict(max=100))],
                      presets=[dict(label=T('A dealer weighing electric cars against petrol cars (an illustration)', '权衡电动车和燃油车的经销商（举例）'), set=dict(e=40, i=35, v=6)), dict(label=T('Your own store staff', '你自己的门店员工'), set=dict(e=90, i=90, v=8))],
                      notes=[dict(when='mine>rv', text=T('**It would push your brand harder** than the rival.', '**它会更用力地推你的品牌**，胜过推竞争品牌。')), dict(when='mine<=rv', text=T('**It pushes the rival first**: your brand loses the seller’s effort.', '**它优先推竞争品牌**：你的品牌输掉了销售方的精力。')),
                             dict(when='e<20||i<20||v<2', text=T('One factor is close to zero, so the product collapses whatever the other two are.', '有一个因素接近零，不管另外两个多高，乘积都会崩塌。'))],
                      caption=T("The rival’s level of 24 is chosen for the demonstration; no real seller was measured.", "竞争品牌的 24 是为演示而设的，没有测量任何真实销售方。"), height=700),
                 chapter=CH['touch']),
            read('touch2', T('Build or buy the sales force', '自建还是外购销售队伍'),
                 p(T("Anderson and Weitz: whether to make a sales force or buy one depends on the situation. Seven conditions, two answers.", "Anderson 和 Weitz：自建还是外购销售队伍，取决于情形。七个条件，两个答案。")),
                 place(T('Seven conditions to place under make your own sales force or buy independent sellers.', '七个条件，放到“自建销售队伍”或“外购独立销售方”下。'), mb_zones, mb_chips, cols=2,
                       done=T("**Make** when marketing activities need specialised knowledge, close coordination and hard-to-monitor effort; **buy** when they are standardised, easy to measure and cheaper from specialists. This is the same logic as the make-or-buy lesson (lesson 13), applied to selling.", "**自建**：营销活动需要专门知识、紧密协调、难以监督的努力；**外购**：活动标准化、易衡量、专业方做更便宜。这与第 13 课的自制或外购是同一套逻辑，只是用在销售上。"), height=780)),
            read('touch3', T('How tightly to hold the reins', '缰绳拉多紧'),
                 p(T("Two ways to steer a sales force (Anderson and Oliver). They go with different kinds of people and different kinds of pay.", "引导销售队伍有两种方式（Anderson 和 Oliver）。它们对应不同类型的人，也对应不同的薪酬方式。")),
                 place(T('Six features to place under behaviour-based or outcome-based control.', '六个特征，放到行为控制或结果控制下。'), ct_zones, ct_chips, cols=2,
                       done=T("**Behaviour-based**: watch how they sell, more fixed pay, suits a salesperson who identifies with the firm. **Outcome-based**: judge what they achieve, more variable pay, suits an independent agency that follows its own goals. With **independent** sellers you can usually only control outcomes.", "**行为控制**：盯怎么卖、固定薪酬更多，适合认同企业的销售员。**结果控制**：看取得了什么、可变薪酬更多，适合按自己目标行事的独立代理。对**独立**销售方，通常只能控制结果。"), height=700)),
            read('name', T('The framework, as the marker wants it', '阅卷人要的框架'),
                 p(T("An **independent sales force** is made of external agents who often represent several companies: independent dealerships (Toyota), retailers or boutiques (David Jones), wholesalers (Metcash). Done well, it buys experienced, motivated sellers focused on a target segment, with a specific value proposition, through specific channels, for a specific time. The difficulty is motivation: how to get them to concentrate on your products and not competitors’ (different cosmetics brands in Sephora, different shoe brands in Foot Locker).",
                     "**独立销售队伍**由外部代理组成，常常同时代表几家公司：独立经销商（Toyota）、零售商或精品店（David Jones）、批发商（Metcash）。做得好，相当于买来有经验、有动力的销售人员，聚焦在某个目标细分、某个价值主张、某些渠道和某段时间。难点是动力：怎样让他们专心卖你的产品，而不是竞争对手的（Sephora 里的不同化妆品品牌，Foot Locker 里的不同鞋品牌）。")),
                 ul(T("**Vroom’s expectancy theory**: motivation is determined by **expectancy** (can I reach the target?), **instrumentality** (will reaching it bring a reward?) and **valence** (is the reward desirable?). For Tesla, a dealer asks whether it can educate buyers about EVs, whether promoting them brings more reward than selling petrol cars, and whether that reward is desirable: all three may be low, which is a reason to sell direct.", "**Vroom 期望理论**：动力由**期望**（我能达到目标吗）、**工具性**（达到后有回报吗）和**效价**（回报有吸引力吗）决定。对 Tesla，经销商会问：能否让买家了解电动车？推广电动车是否比卖燃油车回报更高？这份回报有没有吸引力？三者都可能偏低，这就是直营的理由。"),
                    T("**Incentives** are not always strong motivators and come in forms (cash, trophy, CEO recognition, a seat on the R&D team): what works depends on the person and context.", "**激励**并不总是强有力的动力，且有多种形式（现金、奖杯、CEO 的认可、进入研发团队）：什么有效取决于人和情境。"),
                    T("**Tiering** (Apple): its own stores get the highest support and training for a “high touch” customer; big distributors such as JB Hi-Fi get regular moderate-to-high support; lower-volume ones such as Officeworks get lighter, semi-automated support.", "**分层**（Apple）：自己的门店得到最高的支持和培训，面向“高触达”顾客；JB Hi-Fi 这类大经销商得到常规的中高水平支持；Officeworks 这类销量较小的得到较轻、半自动的支持。"),
                    T("**Pledges** (Anderson and Weitz): commitments that bind the relationship, such as written commitments, exclusivity and tenure, and **idiosyncratic investments** (assets that lose value outside the relationship, such as dedicated training or joint programmes), which signal you are staying.", "**承诺保证**（Anderson 和 Weitz）：约束关系的承诺，如写进协议的承诺、独家性和任期；以及**专用性投资**（离开这段关系就贬值的资产，如专门培训或联合项目），表明你会留下。")),
                 chapter=CH['name']),
            apply_q('apply', SK, T("Take a tea brand sold through supermarkets such as Coles (a reading, nothing verified for Australia). Write four sentences: where a supermarket’s **expectancy, instrumentality or valence** for pushing this brand may be low, and **one** move the brand could make, with a *because*.", "以通过 Coles 这类超市销售的茶叶品牌为例（解读，澳大利亚情况未核实）。写四句话：超市推这个品牌的**期望、工具性或效价**哪一项可能偏低，以及品牌可以采取的**一项**举措，并带“因为”。"),
                    [T("Names which factor is low and why, from the retailer’s side (own brands, many competing brands, margins)", "从零售商一侧说出哪一项偏低及原因（自有品牌、众多竞争品牌、利润）"), T("Says it is a reading and not verified for Australia", "说明这是解读，澳大利亚情况未核实"),
                     T("Proposes a move that changes that factor (a shelf programme, a joint promotion, in-store support tier)", "提出改变那一项的举措（货架方案、联合促销、门店支持分层）"), T("A because linking the move to the factor", "有“因为”把举措和那一项联系起来")],
                    T("This is a reading, since I have not verified how any supermarket treats a tea brand. A supermarket with its own brand ranges, as Coles has, may rate the instrumentality of pushing a branded tea as low, because pushing it may take sales from a range where its margin is higher. The brand could offer a joint promotion that raises the reward to the retailer, such as an exclusive pack, because that lifts instrumentality: promoting this brand then brings a reward better than promoting a rival.",
                      "这是解读，因为我没有核实任何超市如何对待某个茶叶品牌。像 Coles 这样有自有品牌系列的超市，可能认为推广品牌茶的工具性偏低，因为推它可能抢走自有品牌系列的销量，而那里利润更高。品牌可以提供联合促销，提高对零售商的回报，比如独家包装，因为这提高了工具性：推这个品牌带来的回报，好过推竞争对手。"),
                    T("Name the factor, say it is a reading, give one lever.", "点出哪一项，说明是解读，给一个杠杆。")),
            choice('neighbour', T('The look-alike', '长得像的那个'), SK,
                   T("A manufacturer has an independent sales agency selling across a wide area and judges it only on sales results, with mostly variable pay. Which control system is that?", "一家制造商让独立销售代理在大片区域销售，只按销售结果评价，薪酬以可变部分为主。这是哪种控制系统？"),
                   [(T("Outcome-based control", "结果控制"), True), (T("Behaviour-based control", "行为控制"), T("Behaviour-based means close monitoring and direction and more fixed pay.", "行为控制意味着密切监督和指导，以及更多固定薪酬。")),
                    (T("Vertical integration", "纵向一体化"), T("It is an external agency, so the firm is buying, not making.", "它是外部代理，所以企业是外购而不是自建。"))],
                   T("Independent sellers are controlled by outcomes.", "独立销售方靠结果来控制。"), purpose='check', chapter=CH['neighbour']),
            recall('r1', SK, T("From lesson 9: motivation to go the extra mile is supplied by which HR practice?", "来自第 9 课：愿意多做一点的动力，由哪项人力资源做法提供？"),
                   [(T("Motivation practices: recognition and fair reward", "激励做法：认可与公平的回报"), True), (T("Acquisition", "招聘"), T("Hiring does not by itself produce effort.", "招聘本身不产生努力。"))], T("Same theme: motivation is a design choice.", "同一个主题：动力是设计出来的。"), first=True),
            recall('r2', SK, T("From lesson 6: a proposition for a retailer has to answer which question?", "来自第 6 课：面向零售商的主张要回答什么问题？"),
                   [(T("What is in it for them, not for us", "对他们有什么好处，而不是对我们"), True), (T("What our product features are", "我们的产品有什么功能"), T("Benefits, not features.", "要讲利益，不是功能。"))], T("Value proposition applies to the channel too.", "价值主张对渠道同样适用。")),
        ] + exam_three('exam', SK,
                       T("Question. (a) Explain the challenge of working with an independent sales force and Vroom’s expectancy theory. (b) Apply it to a named channel of Hilton Hotels in Australia. (c) Make two recommendations.", "题目。(a) 解释与独立销售队伍合作的挑战，以及 Vroom 的期望理论。(b) 把它应用到澳大利亚 Hilton 酒店的某个明确渠道。(c) 给出两条建议。"),
                       (T("Write the **Explain** part.", "写**解释**部分。"),
                        [T("Independent sellers are external agents, often for several firms, so motivating them to focus on your product is hard", "独立销售方是外部代理，常为几家企业销售，所以很难激励他们聚焦你的产品"), T("Vroom: expectancy, instrumentality and valence", "Vroom：期望、工具性、效价"),
                         T("They multiply, so one weak factor reduces motivation", "三者相乘，一个弱项就降低动力"), T("Incentives depend on the person and context", "激励取决于人和情境")],
                        T("Independent sales forces are external agents, such as dealerships, retailers and wholesalers, who often represent several companies, so the problem is getting them to concentrate on your products and not competitors’. Vroom’s expectancy theory says motivation depends on expectancy, whether the target can be reached, instrumentality, whether reaching it brings a reward, and valence, whether the reward is desirable. Because the factors multiply, one weak factor reduces motivation. Incentives work only if the seller values them, which varies with the person and the context.",
                          "独立销售队伍是外部代理，如经销商、零售商和批发商，常常代表几家企业，所以难点是让他们专心卖你的产品，而不是竞争对手的。Vroom 的期望理论认为动力取决于期望（目标能否达到）、工具性（达到后是否有回报）和效价（回报是否有吸引力）。因为这些因素相乘，一个弱项就会降低动力。激励只有在销售方看重它时才有效，这因人而异、因情境而异。")),
                       (T("Write the **Apply** part.", "写**应用**部分。"),
                        [T("Names the channel: franchisees and owners who run Hilton-branded hotels, or travel booking sites as sellers (not verified), and says which is used", "指明渠道：运营 Hilton 品牌酒店的加盟商和业主，或作为销售方的旅游订房网站（未核实），并说明用哪个"), T("Uses verified facts: 8,239 franchised, 873 managed, 46 owned; Honors benefits when booking through Hilton channels", "用已核实的事实：8,239 家特许、873 家管理、46 家自有；通过 Hilton 渠道预订享 Honors 福利"),
                         T("Applies expectancy, instrumentality and valence with cause and effect", "运用期望、工具性、效价并说明因果"), T("Notes control is by outcomes and pledges (fees, standards, tenure)", "指出控制靠结果和承诺保证（费用、标准、任期）")],
                        T("Take Hilton’s franchisees, who run most of its hotels: about 8,239 against 873 managed and 46 owned at the end of 2025. They are independent owners, and could run another brand. Expectancy is high if the brand’s standards are achievable; instrumentality depends on whether the Hilton name brings bookings, which Honors with 243 million members and Hilton’s booking channels supply, as members book through Hilton channels to get benefits; valence depends on the fees and returns the owner values. Hilton cannot watch daily behaviour, so it controls outcomes through standards, audits and guest scores, and binds franchisees with licence terms and tenure, which are pledges. The weakest factor is the one to fix first.",
                          "以 Hilton 的加盟商为例，他们运营着它的大部分酒店：2025 年底约 8,239 家，对比 873 家管理和 46 家自有。他们是独立业主，也可以经营别的品牌。如果品牌标准可以达到，期望就高；工具性取决于 Hilton 的名字能否带来订单，拥有 2.43 亿会员的 Honors 和 Hilton 的预订渠道提供了这一点，因为会员为享受福利而通过 Hilton 渠道预订；效价取决于业主看重的费用和回报。Hilton 无法每天盯行为，所以通过标准、审核和客人评分控制结果，并用授权条款和任期来绑定加盟商，这些就是承诺保证。最弱的那个因素要先修补。")),
                       (T("Write the **Recommend** part: exactly two.", "写**建议**部分：恰好两条。"),
                        [T("Exactly two from the analysis (raise instrumentality with proof of demand; add pledges)", "恰好两条，从分析里推出（用需求证据提高工具性；增加承诺保证）"), T("Each actionable", "每条可执行"), T("A risk named", "点出风险")],
                        T("First, report to each franchisee the share of its bookings that come through Honors and Hilton channels, so it can see that promoting the brand pays, which raises instrumentality. The risk is revealing data that owners may use in fee talks, so keep it in private reports. Second, add pledges that signal commitment, such as shared marketing programmes and longer terms tied to meeting standards. The risk is rigidity if owners’ markets change, so include review points.",
                          "第一，向每位加盟商报告其订单中通过 Honors 和 Hilton 渠道来的份额，让他看到推广品牌有回报，这提高了工具性。风险是披露的数据被业主用于费用谈判，所以只放在私下的报告里。第二，增加表明承诺的保证，如共享营销项目，以及与达标挂钩的更长期限。风险是业主的市场变化时过于僵化，所以要设复审节点。")),
                       ),
    )
